 private String thoughtSummary(JSONObject m){String thought=m.optString("reasoning");if(thought.isEmpty())return "";long millis=m.optLong("thinkingMillis",-1);return "思考过程"+(millis<0?"":" · "+Math.max(1,millis/1000)+" 秒")+" · "+thought.length()+" 字";}
