 private void prepareReveal(){if(activeAnswer==null)return;String id=activeAnswer.optString("id");if(!reveal.matches(id)){if(!activeAnswer.optString("status").equals("streaming"))return;reveal.begin(id,"",SystemClock.uptimeMillis());}reveal.offer(activeAnswer.optString("text"));}
 private boolean revealing(JSONObject m){return reveal.matches(m.optString("id"))&&reveal.pending();}
