 private void updateStreamStatus(){if(busy&&activeAnswer==null){setTextIfChanged(status,session.summaryStatus);return;}if(activeAnswer==null)return;if(revealing(activeAnswer)&&!busy)setTextIfChanged(status,"正在显示回答…");else if(busy)setTextIfChanged(status,!activeAnswer.optString("phase","chat").equals("chat")||activeAnswer.optString("text").isEmpty()?stageLabel(activeAnswer):"正在生成 · "+activeAnswer.optLong("elapsedMillis",0)/1000+" 秒");}
 private boolean activeVisible(){if(scroll==null||messageAdapter==null||activeAnswer==null||current()==null)return false;JSONArray messages=current().optJSONArray("messages");int last=messageAdapter.getCount()-1;return messages!=null&&messages.optJSONObject(last)==activeAnswer&&SmoothStream.visibleItem(scroll,last)!=null;}
 private void renderSoon(){if(destroyed||!uiActive||streamFrames==null||activeAnswer==null)return;if(!activeVisible()){if(!followTail)reveal.finish();return;}streamFrames.request();}
 private void renderTail(){if(destroyed||!uiActive||activeAnswer==null||!activeVisible())return;int last=messageAdapter.getCount()-1;View item=SmoothStream.visibleItem(scroll,last);if(item==null||!(item.getTag() instanceof Bubble))return;Bubble binding=(Bubble)item.getTag();if(binding.message!=activeAnswer||!binding.streaming)return;prepareReveal();boolean wasPending=revealing(activeAnswer);reveal.advance(SystemClock.uptimeMillis());String answer=visibleAnswer(activeAnswer);boolean changed=rich.updateLive(binding.content,answer);if(changed){tailUpdateCount++;binding.body=rich.liveTail(binding.content);liveBody=binding.body;renderedLiveText=answer;}boolean metadata=setTextIfChanged(binding.stage,stageLabel(activeAnswer));int phaseVisibility=busy&&(answer.isEmpty()||!activeAnswer.optString("phase","chat").equals("chat"))?View.VISIBLE:View.GONE;if(binding.stage.getVisibility()!=phaseVisibility){binding.stage.setVisibility(phaseVisibility);metadata=true;}metadata|=setTextIfChanged(binding.thought,thoughtSummary(activeAnswer));int thoughtVisibility=activeAnswer.optString("reasoning").isEmpty()?View.GONE:View.VISIBLE;if(binding.thought.getVisibility()!=thoughtVisibility){binding.thought.setVisibility(thoughtVisibility);metadata=true;}if(followTail&&(changed||metadata))SmoothStream.stick(scroll,last,item);if(revealing(activeAnswer))streamFrames.request();else if(!busy&&wasPending){render();busy(false);}updateJump();}
