 private void submit(){if(reading){toast("文件正在解析");return;}String originalDraft=draftKey();String value=input.getText().toString().trim();if(value.isEmpty()&&pending.isEmpty())return;if(!hasKey()){settingsAccount();return;}try{JSONObject c=current();if(c==null){String name=value.isEmpty()?pending.get(0).optString("name"):value;c=new JSONObject().put("id",uid()).put("title",name.substring(0,Math.min(30,name.length()))).put("messages",new JSONArray()).put("updated",System.currentTimeMillis());chats().put(c);put(state,"current",c.getString("id"));}JSONArray files=new JSONArray();for(JSONObject f:pending)files.put(f);c.getJSONArray("messages").put(new JSONObject().put("id",uid()).put("role","user").put("text",value).put("files",files).put("status","complete").put("preferredOutput",state.optString("outputFormat","auto")));put(state,"outputFormat","auto");pending.clear();clearDraft(originalDraft);renderAttachments();restoringDraft=true;input.setText("");restoringDraft=false;followTail=true;((InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(input.getWindowToken(),0);save();render();generate(c);}catch(Exception e){error("发送失败",e);}}

